package org.oppo.drawergroups;

/** Build-time configuration. Regenerated by build.sh for each variant. */
public final class BuildConfig {
    /** true: enable the A-Z letter bar spacing hook; false: keep the stock spacing. */
    public static final boolean ENABLE_SPACING_HOOK = true;
    /** Spacing in raw pixels passed to COUITouchSearchView.setItemSpacing(). Stock is 4. */
    public static final int SPACING_PX = 8;

    private BuildConfig() {}
}
